package com.habilitesrandom.item;
import com.habilitesrandom.data.*;import com.habilitesrandom.network.NetworkSync;import com.habilitesrandom.transformation.PowerfulFormService;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.*;import net.minecraft.world.level.Level;
/** Permanent, non-stackable entitlement activation; repeated consumption is rejected. */
public final class PowerfulFruitItem extends Item {public PowerfulFruitItem(Properties p){super(p);}
 @Override public InteractionResult use(Level level,Player player,InteractionHand hand){ItemStack stack=player.getItemInHand(hand);if(!(player instanceof ServerPlayer serverPlayer)||ServerRuntime.server()==null)return InteractionResult.PASS;PlayerProfile profile=PlayerDataManager.get(ServerRuntime.server(),player.getUUID());if(profile.loadout().powerfulFruitActive()){player.sendSystemMessage(Component.translatable("item.habilitesrandom.powerful_fruit.active"));return InteractionResult.FAIL;}PlayerProfile updated=PowerfulFormService.consumeFruit(profile);PlayerDataManager.update(ServerRuntime.server(),player.getUUID(),updated);if(!serverPlayer.isCreative())stack.shrink(1);NetworkSync.sendProfile(serverPlayer);player.sendSystemMessage(Component.translatable("item.habilitesrandom.powerful_fruit.applied"));return InteractionResult.SUCCESS;}
}
